// Checkpoint characters (owner brief 2026-10-20): one cartoon per checkpoint, drawn as hand-authored vector art in one
// family — the same price-tag body, face and proportions — told apart by colour and accessory. Inline SVG, about 2 KB
// each, crisp at any pixel density, no network request. NOT generated by an image model; NOT an official Digikala asset
// (none was supplied, R-26). The configuration's badge_asset_id picks the character; an unknown id (a checkpoint added
// later in A02) gets the character of its position, so a new checkpoint never shows a blank.

const FACE = '<ellipse cx="66" cy="92" rx="9" ry="11" fill="#fff"/><ellipse cx="94" cy="92" rx="9" ry="11" fill="#fff"/>' +
  '<circle cx="68" cy="94" r="5" fill="#1E2129"/><circle cx="96" cy="94" r="5" fill="#1E2129"/>' +
  '<circle cx="70" cy="91.5" r="1.7" fill="#fff"/><circle cx="98" cy="91.5" r="1.7" fill="#fff"/>' +
  '<path d="M70 111q10 9 20 0" stroke="#1E2129" stroke-width="4" fill="none" stroke-linecap="round"/>' +
  '<ellipse cx="55" cy="107" rx="6" ry="3.5" fill="#FF8FA0" opacity=".75"/><ellipse cx="105" cy="107" rx="6" ry="3.5" fill="#FF8FA0" opacity=".75"/>';

const BODY = 'M80 26L124 58Q128 61 128 66V130Q128 142 116 142H44Q32 142 32 130V66Q32 61 36 58Z';
const MAGNIFIER = '<path d="M134 114l11 12" stroke="#7A4A1F" stroke-width="7" stroke-linecap="round"/>' +
  '<circle cx="125" cy="104" r="12" fill="#E8F6FF" fill-opacity=".75" stroke="#5E6573" stroke-width="5"/>' +
  '<path d="M119 99a7 7 0 0 1 7-3" stroke="#fff" stroke-width="2.5" fill="none" stroke-linecap="round"/>';

function tag(c, { back = '', top = '', front = '', hand = '' } = {}) {
  return `<svg viewBox="0 0 160 160" width="100%" height="100%" aria-hidden="true" focusable="false">${back}` +
    `<ellipse cx="80" cy="150" rx="46" ry="6" fill="#000" opacity=".16"/>` +
    `<ellipse cx="56" cy="145" rx="11" ry="6" fill="${c.line}"/><ellipse cx="104" cy="145" rx="11" ry="6" fill="${c.line}"/>` +
    `<path d="M33 98q-15 3-17 18" stroke="${c.body}" stroke-width="10" fill="none" stroke-linecap="round"/>` +
    `<path d="${BODY}" fill="${c.body}" stroke="${c.line}" stroke-width="4" stroke-linejoin="round"/>` +
    `<path d="M128 70V130Q128 142 116 142H100Q118 120 116 70Z" fill="${c.shade}" opacity=".55"/>` +
    `<circle cx="80" cy="52" r="7" fill="${c.line}"/><circle cx="80" cy="52" r="3.5" fill="#fff"/>` +
    `<path d="M127 98q12 0 14 10" stroke="${c.body}" stroke-width="10" fill="none" stroke-linecap="round"/>` +
    `${FACE}${front}${hand}${top}</svg>`;
}

const SPARK = (x, y, s, f) => `<path transform="translate(${x} ${y}) scale(${s})" d="M0-9L2.4-2.4 9 0 2.4 2.4 0 9-2.4 2.4-9 0-2.4-2.4Z" fill="${f}"/>`;

/** Four characters of one family, from the first checkpoint to the last (launch: 3 / 5 / 7 / 10). */
const ART = {
  // «قیمت‌یاب تازه‌کار» — a mint rookie with a sprout and a magnifier
  rookie: tag({ body: '#3CCFA9', shade: '#1E9C7E', line: '#0F5E4C' }, {
    top: '<path d="M80 27q-1-11 2-17" stroke="#0F5E4C" stroke-width="4" fill="none" stroke-linecap="round"/>' +
      '<path d="M82 12q14-9 20 2q-12 7-20-2Z" fill="#7BE07B" stroke="#0F5E4C" stroke-width="3" stroke-linejoin="round"/>' +
      '<path d="M80 16q-13-8-19 3q11 6 19-3Z" fill="#9BEA8F" stroke="#0F5E4C" stroke-width="3" stroke-linejoin="round"/>',
    hand: MAGNIFIER }),
  // «قیمت‌یاب» — a sky-blue explorer: safari hat and magnifier
  finder: tag({ body: '#5AAEFF', shade: '#2F7FD6', line: '#173F73' }, {
    top: '<ellipse cx="80" cy="41" rx="37" ry="7.5" fill="#9A6331" stroke="#4A2C12" stroke-width="3"/>' +
      '<path d="M57 40Q58 15 80 13Q102 15 103 40Z" fill="#B97B3E" stroke="#4A2C12" stroke-width="3" stroke-linejoin="round"/>' +
      '<path d="M58 34H102" stroke="#4A2C12" stroke-width="6"/>',
    hand: MAGNIFIER }),
  // «کارشناس بازار» — a violet market expert: round glasses, a pencil and a checked clipboard
  expert: tag({ body: '#A47BFF', shade: '#7A4BE0', line: '#3E2286' }, {
    front: '<circle cx="66" cy="93" r="13" fill="#fff" fill-opacity=".18" stroke="#1E2129" stroke-width="3.5"/>' +
      '<circle cx="94" cy="93" r="13" fill="#fff" fill-opacity=".18" stroke="#1E2129" stroke-width="3.5"/><path d="M79 92h2" stroke="#1E2129" stroke-width="3.5"/>' +
      '<path d="M45 70l7-7 3 3-7 7Z" fill="#FFC633" stroke="#3E2286" stroke-width="2" stroke-linejoin="round"/>',
    hand: '<rect x="121" y="92" width="27" height="34" rx="4" fill="#F5F6F8" stroke="#5E6573" stroke-width="3"/>' +
      '<rect x="128" y="88" width="13" height="8" rx="2" fill="#5E6573"/>' +
      '<path d="M127 104h15M127 111h15M127 118h9" stroke="#A3A9B3" stroke-width="2.5" stroke-linecap="round"/>' +
      '<path d="M128 104l2 2 4-5" stroke="#0A7A5F" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>' }),
  // «قیمت‌شناس واقعی» — the golden master: crown, red cape and sparkles
  master: tag({ body: '#FFC93C', shade: '#F0A800', line: '#8A5A00' }, {
    back: '<path d="M38 66Q14 118 26 146H134Q146 118 122 66Z" fill="#C42537" stroke="#7A0F22" stroke-width="3" stroke-linejoin="round"/>' +
      SPARK(22, 40, 1, '#FFE27A') + SPARK(140, 30, .8, '#FFFFFF') + SPARK(146, 70, .6, '#FFE27A'),
    top: '<path d="M55 36L60 12L71 25L80 6L89 25L100 12L105 36Z" fill="#FFD84D" stroke="#8A5A00" stroke-width="3" stroke-linejoin="round"/>' +
      '<circle cx="80" cy="28" r="3.6" fill="#E43551"/><circle cx="66" cy="31" r="2.6" fill="#3CCFA9"/><circle cx="94" cy="31" r="2.6" fill="#5AAEFF"/>',
    hand: SPARK(132, 106, 1.1, '#FFFFFF') }),
};

const BY_BADGE = { badge_3: 'rookie', badge_5: 'finder', badge_7: 'expert', badge_10: 'master' };
const ORDER = ['rookie', 'finder', 'expert', 'master'];

/** @param badgeAssetId from the run's configuration; @param index position among enabled checkpoints (fallback) */
export function character(badgeAssetId, index = 0) {
  const k = BY_BADGE[badgeAssetId] || ORDER[Math.min(ORDER.length - 1, Math.max(0, index))];
  return ART[k];
}
